mapper.select:
/* Attd13Mapper.selectNextChangeReqId */
SELECT CONCAT('LC', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'LEAVE_CHANGE_REQ_ID'))
  FROM DUAL

/* Attd13Mapper.selectRepresentativeLeaveId */
SELECT MIN(U.LEAVE_ID)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.REQ_ID       = #{reqId}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'

/* Attd13Mapper.sumOccupiedLeaveDaysOnDateExcludingSelf */
SELECT COALESCE(SUM(
         CASE WHEN U.USE_UNIT_TYPE = '00' THEN 1.0 ELSE U.LEAVE_DAYS END
       ), 0)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.USER_CD      = #{userCd}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'
   AND U.START_DATE   <=  #{targetDate}
   AND U.END_DATE     >=  #{targetDate}
   AND U.LEAVE_ID    != #{excludeLeaveId}

   AND (U.REQ_ID IS NULL OR U.REQ_ID != #{excludeReqId})

/* Attd13Mapper.countDirectUseConflictOnDate */
SELECT COUNT(*)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.USER_CD      = #{userCd}
   AND U.START_DATE   = #{targetDate}
   AND U.REQ_ID IS NULL
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'
   AND U.LEAVE_ID    != #{excludeLeaveId}
   AND ( U.LEAVE_CD   = #{leaveCd}

      OR U.USE_UNIT_TYPE = '00'

       )

/* Attd13Mapper.sumTargetLeaveDays */
SELECT COALESCE(SUM(U.LEAVE_DAYS), 0)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'


   AND U.REQ_ID       = #{reqId}


   AND U.LEAVE_ID     = #{leaveId}

/* Attd13Mapper.sumSelfRestorableDaysOnDate */
SELECT COALESCE(SUM(U.LEAVE_DAYS), 0)
  FROM TB_USER_LEAVE_USE U
  JOIN TB_USER_LEAVE_GRANT G
    ON G.CMPNY_CD = U.CMPNY_CD
   AND G.GRANT_ID = U.GRANT_ID
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'


   AND U.REQ_ID       = #{reqId}


   AND U.LEAVE_ID     = #{leaveId}


   AND G.LEAVE_CD = #{leaveCd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.AVAIL_FROM_DATE <= #{targetDate}
   AND G.AVAIL_TO_DATE   >= #{targetDate}

/* Attd13Mapper.selectGrantAvailToDate */
SELECT G.AVAIL_TO_DATE
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.GRANT_ID = #{grantId}
 LIMIT 1

/* Attd13Mapper.selectMinGrantAvailToDateByReq */
SELECT MIN(G.AVAIL_TO_DATE)
  FROM TB_USER_LEAVE_USE U
  JOIN TB_USER_LEAVE_GRANT G
    ON G.CMPNY_CD = U.CMPNY_CD
   AND G.GRANT_ID = U.GRANT_ID
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.REQ_ID       = #{reqId}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'

/* Attd13Mapper.selectRemainingBorrowGrantIdsByReq */
SELECT DISTINCT G.GRANT_ID
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD     = #{cmpnyCd}
   AND G.GRANT_REASON LIKE '[가불]%'
   AND G.STATUS       = 'ACTIVE'
   AND G.DEL_YN       = 'N'
   AND G.USED_DAYS    >  0
   AND G.GRANT_ID IN (
         SELECT U.GRANT_ID
           FROM TB_USER_LEAVE_USE U
          WHERE U.CMPNY_CD = #{cmpnyCd}
            AND U.REQ_ID   = #{reqId}
            AND U.GRANT_ID IS NOT NULL
       )

/* Attd13Mapper.selectMovableLeaves */ SELECT U.LEAVE_ID AS leaveId , U.LEAVE_CD AS leaveCd , U.START_DATE AS startDate , CASE WHEN U.REQ_ID IS NULL THEN U.LEAVE_DAYS ELSE ( SELECT SUM(S.LEAVE_DAYS) FROM TB_USER_LEAVE_USE S WHERE S.CMPNY_CD = U.CMPNY_CD AND S.REQ_ID = U.REQ_ID AND S.LEAVE_STATUS = 'CONFIRMED' AND S.DEL_YN = 'N' ) END AS leaveDays , U.USE_UNIT_TYPE AS useUnitType , U.PROMOTION_STAGE AS promotionStage , U.DESIGNATOR_TYPE AS designatorType , G.AVAIL_TO_DATE AS availToDate
, U.START_TIME AS startTime , U.END_TIME AS endTime , U.LEAVE_MINUTES AS leaveMinutes FROM TB_USER_LEAVE_USE U LEFT JOIN TB_USER_LEAVE_GRANT G ON G.CMPNY_CD = U.CMPNY_CD AND G.GRANT_ID = U.GRANT_ID WHERE U.CMPNY_CD = #{cmpnyCd} AND U.USER_CD = #{userCd} AND U.LEAVE_STATUS = 'CONFIRMED' AND U.DEL_YN = 'N' AND U.START_DATE >= #{todayYmd}
AND NOT EXISTS ( SELECT 1 FROM TB_USER_ATTD_REQ PR WHERE PR.CMPNY_CD = U.CMPNY_CD AND PR.REQ_ID = U.REQ_ID AND PR.REQ_STATUS = '01' AND PR.DEL_YN = 'N' ) AND ( U.REQ_ID IS NULL OR U.LEAVE_ID = ( SELECT MIN(X.LEAVE_ID) FROM TB_USER_LEAVE_USE X WHERE X.CMPNY_CD = U.CMPNY_CD AND X.REQ_ID = U.REQ_ID AND X.LEAVE_STATUS = 'CONFIRMED' AND X.DEL_YN = 'N' ) ) ORDER BY U.START_DATE ASC, U.LEAVE_ID ASC

mapper.insert:
/* Attd13Mapper.insertChangeRequest */
INSERT INTO TB_LEAVE_CHANGE_REQUEST (
      CHANGE_REQ_ID
    , CMPNY_CD
    , SITE_CD
    , TARGET_USER_CD
    , TARGET_LEAVE_ID
    , INITIATOR_TYPE
    , REQ_TYPE
    , MOVE_TARGET_DATE
    , MOVE_TARGET_HALF_PART
    , MOVE_TARGET_START_TIME
    , REQ_REASON
    , WORKER_RESPONSE
    , REQ_STATUS
    , INITIATOR_USER_CD
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{changeReqId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{targetUserCd}
    , #{targetLeaveId}
    , #{initiatorType}
    , #{reqType}
    , #{moveTargetDate}
    , #{moveTargetHalfPart}
    , #{moveTargetStartTime}
    , #{reqReason}
    , 'PENDING'
    , 'REQUESTED'
    , #{initiatorUserCd}
    , 'N'
    , #{insertNo}
    , NOW()
)

mapper.select:
/* Attd13Mapper.selectChangeRequests */ SELECT R.CHANGE_REQ_ID AS changeReqId , R.CMPNY_CD AS cmpnyCd , R.SITE_CD AS siteCd , R.TARGET_USER_CD AS targetUserCd , TU.USER_NM AS targetUserNm , R.TARGET_LEAVE_ID AS targetLeaveId , LU.START_DATE AS targetStartDate , R.INITIATOR_TYPE AS initiatorType , R.REQ_TYPE AS reqType , R.MOVE_TARGET_DATE AS moveTargetDate , R.REQ_REASON AS reqReason , R.WORKER_RESPONSE AS workerResponse , R.RESPONSE_REASON AS responseReason , R.REJECT_REASON AS rejectReason , R.REQ_STATUS AS reqStatus , R.INITIATOR_USER_CD AS initiatorUserCd , R.CONFIRM_USER_CD AS confirmUserCd , DATE_FORMAT(R.CONFIRM_DATE, '%Y%m%d%H%i%s') AS confirmDate , DATE_FORMAT(R.INSERT_DATE, '%Y%m%d%H%i%s') AS insertDate
, LU.LEAVE_CD AS leaveCd , LT.LEAVE_NM AS leaveNm , LU.USE_UNIT_TYPE AS useUnitType , FNC_CMM_INFO_SRCH(LU.CMPNY_CD, 'SYST_VAL', LU.USE_UNIT_TYPE, 'SYS025') AS unitNm , LU.START_TIME AS startTime , LU.END_TIME AS endTime , CASE WHEN LU.REQ_ID IS NULL THEN LU.LEAVE_DAYS ELSE IFNULL( ( SELECT SUM(X.LEAVE_DAYS) FROM TB_USER_LEAVE_USE X WHERE X.CMPNY_CD = LU.CMPNY_CD AND X.REQ_ID = LU.REQ_ID AND X.LEAVE_STATUS = 'CONFIRMED' AND X.DEL_YN = 'N' ) , LU.LEAVE_DAYS ) END AS leaveDays , LU.LEAVE_MINUTES AS leaveMinutes
, R.MOVE_TARGET_HALF_PART AS moveTargetHalfPart , R.MOVE_TARGET_START_TIME AS moveTargetStartTime
, IFNULL(LU.BRK_WAIVE_YN, 'N') AS brkWaiveYn
, LU.BRK_WAIVE_MIN AS brkWaiveMin FROM TB_LEAVE_CHANGE_REQUEST R LEFT JOIN TB_USER TU ON TU.CMPNY_CD = R.CMPNY_CD AND TU.USER_CD = R.TARGET_USER_CD LEFT JOIN TB_USER_LEAVE_USE LU ON LU.CMPNY_CD = R.CMPNY_CD AND LU.LEAVE_ID = R.TARGET_LEAVE_ID LEFT JOIN TB_LEAVE_TYPE_MGMT LT ON LT.CMPNY_CD = LU.CMPNY_CD AND LT.LEAVE_CD = LU.LEAVE_CD WHERE R.CMPNY_CD = #{cmpnyCd} AND R.DEL_YN = 'N'
AND R.SITE_CD IN
#{sc}
AND R.REQ_STATUS = #{reqStatus}
AND TU.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND R.TARGET_USER_CD IN ( SELECT NU.USER_CD FROM TB_USER NU WHERE NU.CMPNY_CD = #{cmpnyCd} AND NU.SITE_CD = #{nodeSiteCd}
AND NU.NODE_CD IN ( WITH RECURSIVE sub AS ( SELECT N.NODE_CD FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{nodeSiteCd} AND N.NODE_CD = #{nodeCd} UNION ALL SELECT C.NODE_CD FROM TB_SITE_NODE C JOIN sub S2 ON C.CMPNY_CD = #{cmpnyCd} AND C.SITE_CD = #{nodeSiteCd} AND C.PARENT_NODE_CD = S2.NODE_CD ) SELECT NODE_CD FROM sub )
AND NU.NODE_CD = #{nodeCd}
)
ORDER BY R.INSERT_DATE DESC, R.CHANGE_REQ_ID DESC

mapper.update:
/* Attd13Mapper.applyWorkerResponse */
UPDATE TB_LEAVE_CHANGE_REQUEST
   SET WORKER_RESPONSE = #{workerResponse}
     , RESPONSE_REASON = #{responseReason}
     , REQ_STATUS      = #{reqStatus}
     , UPDATE_NO       = #{updateNo}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD       = #{cmpnyCd}
   AND CHANGE_REQ_ID  = #{changeReqId}
   AND TARGET_USER_CD = #{targetUserCd}
   AND REQ_STATUS     = 'REQUESTED'
   AND DEL_YN         = 'N'

/* Attd13Mapper.confirmChangeRequest */
UPDATE TB_LEAVE_CHANGE_REQUEST
   SET REQ_STATUS      = 'CONFIRMED'
     , CONFIRM_USER_CD = #{confirmUserCd}
     , CONFIRM_DATE    = NOW()
     , UPDATE_NO       = #{confirmUserCd}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD      = #{cmpnyCd}
   AND CHANGE_REQ_ID = #{changeReqId}
   AND REQ_STATUS    = 'AGREED'
   AND DEL_YN        = 'N'

/* Attd13Mapper.rejectChangeRequest */
UPDATE TB_LEAVE_CHANGE_REQUEST
   SET REQ_STATUS      = 'REJECTED'
     , REJECT_REASON   = #{rejectReason}
     , CONFIRM_USER_CD = #{confirmUserCd}
     , CONFIRM_DATE    = NOW()
     , UPDATE_NO       = #{confirmUserCd}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD      = #{cmpnyCd}
   AND CHANGE_REQ_ID = #{changeReqId}
   AND REQ_STATUS    = 'AGREED'
   AND DEL_YN        = 'N'

