/* Attd13Mapper.insertMovedLeaveUse */
INSERT INTO TB_USER_LEAVE_USE (
      LEAVE_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD
    , LEAVE_CD
    , REQ_ID
    , GRANT_ID
    , START_DATE
    , START_TIME
    , END_DATE
    , END_TIME
    , USE_UNIT_TYPE
    , LEAVE_DAYS
    , LEAVE_MINUTES
    , BRK_WAIVE_YN
    , BRK_WAIVE_REQ_DTIME
    , BRK_WAIVE_MIN
    , LEAVE_REASON
    , EVIDENCE_FILE_ID
    , LEAVE_STATUS
    , PROMOTION_STAGE
    , DESIGNATOR_TYPE
    , ORIG_DESIGNATED_DATE
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{leaveId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{leaveCd}
    , #{reqId}
    , #{grantId}
    , #{startDate}
    , #{startTime}
    , #{endDate}
    , #{endTime}
    , #{useUnitType}
    , #{leaveDays}
    , #{leaveMinutes}
    , CASE WHEN #{brkWaiveYn} = 'Y' THEN 'Y' ELSE 'N' END
    , CASE WHEN #{brkWaiveYn} = 'Y' THEN #{brkWaiveReqDtime} ELSE NULL END
    , CASE WHEN #{brkWaiveYn} = 'Y' THEN #{brkWaiveMin} ELSE NULL END
    , #{leaveReason}
    , #{evidenceFileId}
    , 'CONFIRMED'
    , IFNULL(#{promotionStage}, 'NONE')
    , IFNULL(#{designatorType}, 'VOLUNTARY')
    , #{origDesignatedDate}
    , 'N'
    , #{insertNo}
    , NOW()
)

mapper.update:
/* Attd13Mapper.moveLeaveUseDate */
UPDATE TB_USER_LEAVE_USE
   SET ORIG_DESIGNATED_DATE = IFNULL(ORIG_DESIGNATED_DATE, START_DATE)
     , START_DATE           = #{newDate}
     , END_DATE             = #{newDate}
     , UPDATE_NO            = #{updateNo}
     , UPDATE_DATE          = NOW()
 WHERE CMPNY_CD     = #{cmpnyCd}
   AND LEAVE_ID     = #{leaveId}
   AND LEAVE_STATUS = 'CONFIRMED'
   AND DEL_YN       = 'N'

/* Attd13Mapper.cancelLeaveUse */
UPDATE TB_USER_LEAVE_USE
   SET LEAVE_STATUS  = 'CANCELLED'
     , CANCEL_REASON = #{cancelReason}
     , CANCEL_DATE   = NOW()
     , UPDATE_NO     = #{updateNo}
     , UPDATE_DATE   = NOW()
 WHERE CMPNY_CD     = #{cmpnyCd}
   AND LEAVE_ID     = #{leaveId}
   AND LEAVE_STATUS = 'CONFIRMED'
   AND DEL_YN       = 'N'

